from numpy import *

def puis(x,y):
    p=1
    for i in range(y):
        p=p*x
    return p
#----------------------------------------------
def conv16_10(ch):
    s=0
    for i in range(len(ch)):
        if '0'<=ch[i]<='9':
            s=s+int(ch[i])*puis(16,len(ch)-i-1)
        else:
            s=s+(ord(ch[i])-55)*puis(16,len(ch)-i-1)
    return s
